const seen = new WeakMap<object, Record<string, string>>();
return (c) => {
  const cond = c as { vars?: Record<string, unknown> };
  if (!cond.vars || Object.keys(cond.vars).length === 0) return {};
  const hit = seen.get(c);
  if (hit) return hit;
  const v = resolve(cond.vars);
  seen.set(c, v);
  return v;
};

